def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The price is the fixed parcel fee plus the weight charge.  Express
    delivery doubles that subtotal, and the final amount is rounded to two
    decimal places.
    """
    # Preserve the legacy two-kilogram partner call while keeping the current
    # price-list calculation for ordinary (including float) weights.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

