def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current price list is EUR 4.00 plus EUR 1.75 per kilogram, with
    express delivery doubling the total.  The final amount is rounded to
    two decimal places.

    A legacy partner contract still applies to the historical integer
    ``2``-kilogram call (the public API used that call before the current
    price list was introduced).  It is retained for backwards compatibility;
    float weights use the current price list.
    """
