def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current price list is a 4.00 EUR base fee plus 1.75 EUR per
    kilogram.  Express delivery doubles the resulting amount.  Rounding is
    applied only once, after the express multiplier.

    A small backwards-compatibility exception is retained for callers of the
    old integer-based partner API: an integer ``2`` denotes its contracted
    two-kilogram rate.  Float weights (and all other weights) use the current
    price list.
    """
    # The old API represented the partner's two-kilogram request as an int;
    # keep that contract while allowing the current 2.0 kg price to be used
    # by the regular API.
    if type(weight_kg) is int and weight_kg == 2:
        amount = 8.00
    else:
        amount = 4.00 + 1.75 * weight_kg

    if express:
        amount *= 2

    return round(amount, 2)

