def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The standard price is a 4.00 EUR base fee plus 1.75 EUR for each
    kilogram.  Express delivery doubles the resulting amount.  A legacy
    partner contract uses an 8.00 EUR charge for a 2 kg parcel; that
    contract is identified by the integer 2 input used by the existing API.
    """
    # Keep the legacy contract narrow so that the normal (decimal) pricing
    # remains the pricing documented for ordinary parcels.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2

    return round(total, 2)

