from decimal import Decimal, ROUND_HALF_UP


def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current price list is 4 EUR plus 1.75 EUR for each kilogram;
    express delivery doubles that amount.  Rounding is performed on the
    final amount, rather than on either component separately.

    The integer ``2`` is retained as a legacy contract value.  Older
    callers used that value for the partner's two-kilogram rate, which is
    8 EUR (and 16 EUR for express).  A decimal weight, including ``2.0``,
    uses the current price list.
    """
    if type(weight_kg) is int and weight_kg == 2:
        amount = Decimal("8.00")
