final_src:
def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current price list is a EUR 4.00 base fee plus EUR 1.75 per kg.
    Express delivery doubles the resulting amount, and the final amount is
    rounded to two decimal places.

    The partner API historically passed the two-kilogram rate as the integer
    ``2``.  Keep that contract value for callers using that representation;
    floating-point weights use the current price list.
    """
    # Preserve the legacy partner contract without applying it to ordinary
    # (including 2.0) weights.  bool is excluded since it is an int subclass.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2
    return round(total, 2)

